-- 984_state_exec_seed_batch_e.sql
-- Phase 141 (v2.18 State Leaders), plan 141-07.
-- GENERATED by backend/scripts/gen-state-exec-seed.mjs from live-verified (June 2026) roster.
-- Seeds 35 in-scope elected Big-5 offices across: AZ, DE, ID, LA, MT, NM, SC, WY.
-- Idempotent (NOT EXISTS / ON CONFLICT guards). external_id = -(fips*100000+seq) except AK/AZ collision offsets.
-- Run: psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f backend/migrations/984_state_exec_seed_batch_e.sql

BEGIN;

